#!/usr/bin/env python3
# Generated by Claude Fable 5 (Anthropic)
"""Per-callback exec-time stats from ONE traced FISH session (CTF via
babeltrace2), self-contained: labels come from the session's own init events.

Output JSON: {"cbs": {cb_addr: {"node": .., "entity": .., "n": int,
"sum_ns": int, "sum2_ns": float, "min_ns": int, "max_ns": int}}, ...}

usage: cb_overhead_extract.py <session_dir> <out.json>
"""
import glob
import json
import os
import re
import sqlite3
import subprocess
import sys
from bisect import bisect_right
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

TZ = ZoneInfo(os.environ.get('FISH_TZ', 'Europe/Amsterdam'))

LINE = re.compile(
    r'^\[(?P<ts>\d{2}:\d{2}:\d{2}\.\d{9})\]\s+\(.*?\)\s+\S+\s+'
    r'(?P<event>[\w:]+):\s+\{(?P<rest>.*)\}\s*$')
KV = re.compile(r'(\w+)\s*=\s*(?:"([^"]*)"|([^,}]+))')


def kvs(text):
    out = {}
    for m in KV.finditer(text):
        out[m.group(1)] = m.group(2) if m.group(2) is not None else m.group(3).strip()
    return out


def main():
    sdir, outp = sys.argv[1], sys.argv[2]
    trace = None
    for root, dirs, files in os.walk(os.path.join(sdir, 'ros2')):
        if 'metadata' in files:
            trace = root
            break
    if not trace:
        json.dump({'error': 'no trace'}, open(outp, 'w'))
        return

    # ---- absolute-time anchor: session name is container-UTC (see
    # ingest_pg.session_start_ts fix) → local date for babeltrace's local
    # time-of-day; day rollover handled below.
    mname = re.search(r'(\d{8})_(\d{6})', os.path.basename(sdir.rstrip('/')))
    epoch_base = None
    if mname:
        d0, t0 = mname.group(1), mname.group(2)
        dt = datetime(int(d0[:4]), int(d0[4:6]), int(d0[6:8]),
                      int(t0[:2]), int(t0[2:4]), int(t0[4:6]),
                      tzinfo=timezone.utc).astimezone(TZ)
        epoch_base = int(datetime(dt.year, dt.month, dt.day,
                                  tzinfo=TZ).timestamp()) * 1_000_000_000

    # ---- CUDA runtime intervals from the session's own nsys sqlite
    # (absolute epoch ns via the ingest_pg corrected-session-start logic) —
    # used to flag callbacks that issue CUDA calls inside their spans.
    cuda_iv = {}     # tid → (sorted starts, ends)
    for sq in glob.glob(os.path.join(sdir, 'nsys', '*.sqlite')):
        try:
            conn = sqlite3.connect(f'file:{sq}?mode=ro', uri=True)
            row = conn.execute(
                'SELECT utcEpochNs, systemClockNs, utcTime, localTime '
                'FROM TARGET_INFO_SESSION_START_TIME LIMIT 1').fetchone()
            off = 0
            if row:
                frac = (int(row[0]) % 1_000_000_000) if row[0] is not None else 0
                if row[2]:
                    dtu = datetime.fromisoformat(row[2]).replace(tzinfo=timezone.utc)
                    off = int(dtu.timestamp()) * 1_000_000_000 + (
                        dtu.microsecond * 1000 if dtu.microsecond else frac)
                elif row[0] is not None:
                    off = int(row[0])
            tmp = {}
            for st, en, gtid in conn.execute(
                    'SELECT start, end, globalTid FROM CUPTI_ACTIVITY_KIND_RUNTIME'):
                tid = int(gtid) & 0xFFFFFF
                tmp.setdefault(tid, []).append((off + int(st), off + int(en or st)))
            conn.close()
            for tid, iv in tmp.items():
                iv.sort()
                cur = cuda_iv.setdefault(tid, [[], []])
                cur[0].extend(x[0] for x in iv)
                cur[1].extend(x[1] for x in iv)
        except Exception:
            continue
    for tid in cuda_iv:
        pairs = sorted(zip(*cuda_iv[tid]))
        cuda_iv[tid] = ([a for a, _ in pairs], [b for _, b in pairs])

    def span_has_cuda(tid, t0, t1):
        iv = cuda_iv.get(tid)
        if not iv:
            return False
        i = bisect_right(iv[0], t1) - 1
        return i >= 0 and iv[1][i] >= t0

    node_of_handle = {}      # node_handle → node name
    sub_topic = {}           # subscription_handle → (topic, node_handle)
    rs_sub = {}              # subscription (rclcpp) → subscription_handle
    cb_label = {}            # cb → (node, entity)
    timer_cb = {}            # timer_handle → cb
    timer_period = {}
    srv_name = {}            # service_handle → (service, node_handle)
    open_start = {}          # vtid → (cb, day_sec_ns)
    stats = {}

    def label_for(cb):
        return cb_label.get(cb, (None, None))

    def note(cb, node, ent):
        if cb and cb not in cb_label:
            cb_label[cb] = (node, ent)

    def ts_ns(hms):
        h, m, rest = hms.split(':')
        s, ns = rest.split('.')
        return ((int(h) * 3600 + int(m) * 60 + int(s)) * 1_000_000_000 + int(ns))

    proc = subprocess.Popen(['babeltrace2', trace], stdout=subprocess.PIPE,
                            stderr=subprocess.DEVNULL, text=True, bufsize=1 << 20)
    day_offset = 0
    last_ts = None
    for line in proc.stdout:
        m = LINE.match(line)
        if not m:
            continue
        ev = m.group('event')
        if ev not in (
            'ros2:callback_start', 'ros2:callback_end', 'ros2:rcl_node_init',
            'ros2:rcl_subscription_init', 'ros2:rclcpp_subscription_init',
            'ros2:rclcpp_subscription_callback_added', 'ros2:rcl_timer_init',
            'ros2:rclcpp_timer_callback_added', 'ros2:rclcpp_timer_link_node',
            'ros2:rcl_service_init', 'ros2:rclcpp_service_callback_added',
            'ros2:rcl_client_init',
            'ros2:fish_rclpy_service_callback_added',
            'ros2:fish_rclpy_subscription_callback_added',
            'ros2:fish_rclpy_timer_callback_added',
            'ros2:fish_rclcpp_waitable_init', 'ros2:fish_rclcpp_receive_link',
        ):
            continue
        p = kvs(m.group('rest'))
        t = ts_ns(m.group('ts'))
        if last_ts is not None and t < last_ts - 12 * 3600 * 1_000_000_000:
            day_offset += 24 * 3600 * 1_000_000_000
        last_ts = t
        t += day_offset
        # vtid lives in the stream context — babeltrace prints it in the
        # second {...} group; our regex grabbed only the last braces. Fall
        # back: parse vtid from the raw line.
        if ev in ('ros2:callback_start', 'ros2:callback_end'):
            vm = re.search(r'vtid\s*=\s*(\d+)', line)
            vtid = vm.group(1) if vm else '?'
            cb = p.get('callback')
            if ev.endswith('start'):
                open_start[vtid] = (cb, t)
            else:
                st = open_start.pop(vtid, None)
                if st and st[0] == cb:
                    d = t - st[1]
                    if 0 <= d < 60_000_000_000:
                        s = stats.setdefault(cb, {'n': 0, 'sum': 0, 'sum2': 0.0,
                                                  'min': d, 'max': d, 'gpu': False})
                        s['n'] += 1
                        s['sum'] += d
                        s['sum2'] += float(d) * d
                        s['min'] = min(s['min'], d)
                        s['max'] = max(s['max'], d)
                        if (not s['gpu']) and epoch_base is not None and cuda_iv:
                            if span_has_cuda(int(vtid), epoch_base + st[1],
                                             epoch_base + t):
                                s['gpu'] = True
        elif ev == 'ros2:rcl_node_init':
            ns = p.get('namespace', '') or ''
            nm = p.get('node_name', '') or ''
            full = (ns.rstrip('/') + '/' + nm).replace('//', '/')
            node_of_handle[p.get('node_handle')] = full
        elif ev == 'ros2:rcl_subscription_init':
            sub_topic[p.get('subscription_handle')] = (p.get('topic_name'),
                                                      p.get('node_handle'))
        elif ev == 'ros2:rclcpp_subscription_init':
            rs_sub[p.get('subscription')] = p.get('subscription_handle')
        elif ev in ('ros2:rclcpp_subscription_callback_added',
                    'ros2:fish_rclpy_subscription_callback_added'):
            sh = p.get('subscription_handle') or rs_sub.get(p.get('subscription'))
            tp, nh = sub_topic.get(sh, (None, None))
            note(p.get('callback'), node_of_handle.get(nh),
                 f'sub:{tp}' if tp else 'sub:?')
        elif ev == 'ros2:rcl_timer_init':
            timer_period[p.get('timer_handle')] = p.get('period')
        elif ev in ('ros2:rclcpp_timer_callback_added',
                    'ros2:fish_rclpy_timer_callback_added'):
            timer_cb[p.get('timer_handle')] = p.get('callback')
            note(p.get('callback'), None,
                 f"tmr:{timer_period.get(p.get('timer_handle'), '?')}ns")
        elif ev == 'ros2:rclcpp_timer_link_node':
            cb = timer_cb.get(p.get('timer_handle'))
            if cb and cb in cb_label:
                node = node_of_handle.get(p.get('node_handle'))
                cb_label[cb] = (node, cb_label[cb][1])
        elif ev == 'ros2:rcl_service_init':
            srv_name[p.get('service_handle')] = (p.get('service_name'),
                                                 p.get('node_handle'))
        elif ev == 'ros2:rcl_client_init':
            # executor execute_client wrap uses the rcl client handle as the
            # cb-id, so the handle itself labels the spans
            note(p.get('client_handle'),
                 node_of_handle.get(p.get('node_handle')),
                 f"cli:{p.get('service_name', '?')}")
        elif ev in ('ros2:rclcpp_service_callback_added',
                    'ros2:fish_rclpy_service_callback_added'):
            sn, nh = srv_name.get(p.get('service_handle'), (None, None))
            note(p.get('callback'), node_of_handle.get(nh),
                 f'serv:{sn}' if sn else 'serv:?')
        elif ev == 'ros2:fish_rclcpp_receive_link':
            # NITROS subscriptions skip rclcpp_subscription_init; the receive
            # link pairs cb ↔ rcl subscription handle directly.
            cb = p.get('callback')
            if cb and (cb not in cb_label or cb_label[cb][1] == 'sub:?'
                       or cb_label[cb][0] is None):
                tp, nh = sub_topic.get(p.get('subscription_handle'), (None, None))
                if tp:
                    cb_label[cb] = (node_of_handle.get(nh), f'sub:{tp}')
        elif ev == 'ros2:fish_rclcpp_waitable_init':
            nh = p.get('node_handle')
            if nh and nh != '0x0':
                note(p.get('waitable'), node_of_handle.get(nh), 'waitable')
    proc.wait()

    out = {'session_dir': sdir, 'cbs': {}}
    for cb, s in stats.items():
        node, ent = label_for(cb)
        out['cbs'][cb] = {'node': node, 'entity': ent, 'n': s['n'],
                          'sum_ns': s['sum'], 'sum2_ns': s['sum2'],
                          'min_ns': s['min'], 'max_ns': s['max'],
                          'gpu': bool(s.get('gpu'))}
    json.dump(out, open(outp, 'w'))
    print(f"{os.path.basename(sdir)}: {len(stats)} cbs, "
          f"{sum(s['n'] for s in stats.values())} execs", flush=True)


if __name__ == '__main__':
    main()
